- name: Require reviewed first release, prepare and execute only worker2
  shell: pwsh
  run: |
    $ErrorActionPreference = 'Stop'
    $PSNativeCommandUseErrorActionPreference = $false
    $releasePath = 'tests/selections/1536-hot-worker-windows.json'
    $category = 'fr063-hot-worker-ready-disposition'
    $evidence = 'TestResults/fr063-hot-worker-windows'
    New-Item -ItemType Directory -Path $evidence -Force | Out-Null
    function Require([bool]$Condition, [string]$Message) {
      if (-not $Condition) { throw $Message }
    }
    function GitValue([string[]]$GitArgs) {
      $value = & git @GitArgs
      Require ($LASTEXITCODE -eq 0) "Git read failed: $($GitArgs -join ' ')"
      return $value
    }
    function DllPins {
      @('BookOfEternityClient.Tests/bin/Debug/net8.0/BookOfEternityClient.dll',
        'BookOfEternityClient.Tests/bin/Debug/net8.0/BookOfEternityClient.Tests.dll',
        'BookOfEternityClient.IntegrationTests/bin/Debug/net8.0/BookOfEternityClient.dll',
        'BookOfEternityClient.IntegrationTests/bin/Debug/net8.0/BookOfEternityClient.IntegrationTests.dll') | ForEach-Object {
        [ordered]@{ Path = $_; Bytes = (Get-Item -LiteralPath $_).Length; Sha256 = (Get-FileHash -LiteralPath $_ -Algorithm SHA256).Hash }
      }
    }
    function OwnedPrefix {
      @(Get-ChildItem -LiteralPath ([IO.Path]::GetTempPath()) -Force -Filter 'boe-gameengine-turnlifecycle-*' | Sort-Object FullName | ForEach-Object FullName)
    }
    function InvokeBounded([string]$Label, [string[]]$InvocationArgs) {
      $prior = @(Get-ChildItem TestResults/test-categories -Directory -ErrorAction SilentlyContinue | ForEach-Object FullName)
      $started = [DateTimeOffset]::UtcNow
      & pwsh -NoLogo -NoProfile -File ./scripts/test-csharp.ps1 @InvocationArgs *>&1 | Tee-Object "$evidence/$Label.stdout.log" | Out-Host
      $native = $LASTEXITCODE
      $ended = [DateTimeOffset]::UtcNow
      $new = @(Get-ChildItem TestResults/test-categories -Directory | Where-Object FullName -NotIn $prior)
      $record = [ordered]@{ Label = $Label; Argv = @('pwsh', '-NoLogo', '-NoProfile', '-File', 'scripts/test-csharp.ps1') + $InvocationArgs; Source = $env:GITHUB_SHA; StartedUtc = $started.ToString('O'); EndedUtc = $ended.ToString('O'); NativeExit = $native; ResultDirectories = @($new.FullName) }
      $record | ConvertTo-Json -Depth 12 | Set-Content "$evidence/$Label.native.json" -Encoding utf8NoBOM
      Require ($new.Count -eq 1) "Expected exactly one new result directory for $Label."
      return [pscustomobject]@{ NativeExit = $native; Directory = $new[0].FullName }
    }

var executable = OperatingSystem.IsWindows() ? "pwsh.exe" : "pwsh";
var shell = (Environment.GetEnvironmentVariable("PATH") ?? "").Split(Path.PathSeparator)
    .Select(path => Path.GetFullPath(Path.Combine(path, executable))).FirstOrDefault(File.Exists)
    ?? throw new InvalidOperationException("PowerShell 7 fixture executable is unavailable.");
var input = new QueuedConsoleInputSource([]);
var logger = new SpiritualLifecycleTestLogger();
var engine = CreateGameEngine(input, settings =>
{
    InertRealmSettings(settings); settings.AutosaveIntervalTurns = 0;
    settings.GmWorkerBridgeProfiles.Add(GmWorkerBridgeTestFixtures.ValidationRepairCodexProfile() with
        { Enabled = true, LaunchCommand = $"\"{shell}\" -NoLogo -NoProfile -File \"{scriptPath}\"", TimeoutSeconds = 15 });
}, fileSystem: files, logger: logger);
GetPrivateField<GameLoop>(engine, "_gameLoop").SetSession("session_hot_actual_worker", 42);
await GetPrivateField<StateManager>(engine, "_stateManager").RefreshGameStateAsync();
await SessionOperationContext.RunParticipatingCurrentSessionAsync(files, async () =>

        using var deadlineStop = new CancellationTokenSource();
        var deadline = Task.Delay(TimeSpan.FromSeconds(40), deadlineStop.Token);
        Task<bool>? repairWait = null;
        var failures = new List<Exception>();
        var accepted = false;
        var guardFired = false;
        try
        {
            repairWait = InvokePrivateAsync<bool>(engine, "WaitForContractRepairAsync", "hot actual worker control",
                new List<ValidationIssue> { new(weatherPath, IssueSeverity.Error, "Synthetic weather repair owner control.",
                    code: "normalized_weather_missing_description") }, 1, backup, generation);
            if (await Task.WhenAny(repairWait, deadline) != repairWait)
            {
                guardFired = true;
                throw new TimeoutException("Actual worker repair Wait exceeded the fixture's protective 40s bound.");
            }
            accepted = await repairWait;
        }
        catch (Exception failure) { failures.Add(failure); }
        finally
        {
            await deadlineStop.CancelAsync();
            if (repairWait is { IsCompleted: false }) input.Enqueue(Key(ConsoleKey.Escape));
            // A worker fallback enters the real ordinary Ready/Escape loop.
            // Join that owner and the guard before participation/root disposal.
            try { if (repairWait is not null) await repairWait; }
            catch (Exception failure)
            {
                if (!failures.Contains(failure)) failures.Add(failure);
            }
            try { await deadline; }
            catch (OperationCanceledException failure) when (failure.CancellationToken == deadlineStop.Token) { }
            catch (Exception failure)
            {
                if (!failures.Contains(failure)) failures.Add(failure);
            }
            armed = false;
        }
        // Retain the actual worker result even when fallback/launch/apply fails;
        // a diagnostic failure must not replace the primary owner failure.
        try
        {
            WritePhysicalInjuryDiagnostic("fr063_hot_actual_worker_settled_before_oracles", new
            {
                failReadyPublication, guardFired, accepted, readyCuts, appliedTaskAtCut,
                WaitSettled = repairWait?.IsCompleted, GuardSettled = deadline.IsCompleted,
                EngineDiagnostics = logger.Describe(),
                Platform = System.Runtime.InteropServices.RuntimeInformation.OSDescription,
                WorkerExecutable = shell,
                Audit = await new GmWorkerAuditLog(files).ReadEventsAsync(),
                LatestTask = await files.ReadFileAsync(GmWorkerValidationRepairDelegator.LatestValidationRepairTaskPath),
                Failures = failures.Select(failure => failure.ToString()).ToArray(), request.RequestId, generation
            });
        }
        catch (Exception failure) { failures.Add(failure); }
        if (failures.Count == 1) System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(failures[0]).Throw();
        if (failures.Count > 1) throw new AggregateException("Actual worker fixture and settled diagnostics failed.", failures);
        Assert.True(accepted); Assert.Equal(failReadyPublication ? 1 : 0, readyCuts);
        var audit = await new GmWorkerAuditLog(files).ReadEventsAsync();
        var applied = Assert.Single(audit, row => row.EventType == "proposal-applied");
        var task = GmWorkerJson.Deserialize<WorkerTaskPacket>((await files.ReadFileAsync(
            GmWorkerValidationRepairDelegator.LatestValidationRepairTaskPath))!)!;
        Assert.Equal(task.TaskId, applied.TaskId); Assert.Equal(request.SessionId, task.SourceTurn.SessionId);
        Assert.Equal(request.RequestId, task.SourceTurn.RequestId); Assert.Equal(43, task.SourceTurn.TurnNumber);
        Assert.Equal(generation, task.SessionGeneration);
        if (failReadyPublication) Assert.Equal(task.TaskId, appliedTaskAtCut);
        Assert.Equal(before, await files.ReadFileBytesAsync(weatherPath));
        Assert.Null(await files.ReadFileBytesAsync(readyPath));
        Assert.Null(await files.ReadFileBytesAsync("game_state/control/validation_repair_request.json"));
        var ledger = (await files.ReadFileAsync("game_state/control/gm_trajectory_ledger.jsonl"))!
            .Split('\n', StringSplitOptions.RemoveEmptyEntries).Select(line => JsonNode.Parse(line)!.AsObject()).ToArray();
        var acceptedRow = Assert.Single(ledger, row => row["requestId"]?.GetValue<string>() == request.RequestId &&
            row["sessionId"]?.GetValue<string>() == request.SessionId && row["turnNumber"]?.GetValue<int>() == 43 &&
            row["validation"]?["acceptanceScope"]?.GetValue<string>() ==
                (failReadyPublication ? "worker_apply_gate" : "correlated_repair_ready"));
        Assert.Equal(failReadyPublication ? "worker_apply_gate_accepted" : "validation_repair_ready",
            acceptedRow["terminal"]!["kind"]!.GetValue<string>());
        Assert.False(acceptedRow["validation"]!["fullCanonicalStateAccepted"]!.GetValue<bool>());
        var diagnostic = InvokePrivateValue<JsonObject>(engine, "ExportHotOrdinarySubmissionDiagnostic");
        Assert.True(diagnostic["binding"]!["actualStageCompleted"]!.GetValue<bool>());
        Assert.Equal("Unavailable", diagnostic["custody"]!["status"]!.GetValue<string>());
        Assert.Equal("WorkerDispositionNotIntegrated", diagnostic["custody"]!["reason"]!.GetValue<string>());
        Assert.Equal(!failReadyPublication, diagnostic["custody"]!["readyDeleteReturned"]!.GetValue<bool>());
        Assert.Equal(!failReadyPublication, diagnostic["custody"]!["readyReleaseReturned"]!.GetValue<bool>());
        foreach (var key in new[] { "hasS", "hasB", "hasM3" }) Assert.False(diagnostic[key]!.GetValue<bool>());
        WritePhysicalInjuryDiagnostic("fr063_hot_actual_worker_disposition", new
            { failReadyPublication, readyCuts, appliedTaskAtCut, applied, task, diagnostic, request.RequestId, generation });
        return true;
    });
}

namespace BookOfEternityClient.Services.GmWorkers;

internal enum GmWorkerBackendRequest { Auto, SystemdUser, NativeLineage }
internal enum GmWorkerRequiredCapability { NeutralHost, WorkerRelease, SyntheticWorkerRelease }
public enum GmWorkerBackend { None, WindowsJob, NativeLineage }
internal enum GmWorkerBackendAvailability { NotImplemented, NotQualified, Unsupported, PreflightRequired, Available }

internal sealed record GmWorkerBackendSelection(
    GmWorkerBackendRequest Requested,
    GmWorkerRequiredCapability Capability,
    GmWorkerBackend Backend,
    GmWorkerBackendAvailability Availability,
    string Guarantee,
    string Reason,
    GmWorkerBackendAvailability SystemdAvailability)
{
    internal bool CanStart => Availability is GmWorkerBackendAvailability.Available or GmWorkerBackendAvailability.PreflightRequired;
}

internal static class GmWorkerBackendSelector
{
    internal const string NativeGuarantee = "ordinary-same-namespace-lineage";

    internal static GmWorkerBackendSelection Select(GmWorkerBackendRequest request,
        GmWorkerRequiredCapability capability, bool windows, bool linux)
    {
        GmWorkerBackendSelection Unavailable(GmWorkerBackendAvailability state, string reason) =>
            new(request, capability, GmWorkerBackend.None, state, "none", reason,
                GmWorkerBackendAvailability.NotImplemented);
        if (!Enum.IsDefined(request) || !Enum.IsDefined(capability))
            return Unavailable(GmWorkerBackendAvailability.Unsupported, "Unknown owned-launch request.");
        if (capability == GmWorkerRequiredCapability.SyntheticWorkerRelease)
            return Unavailable(GmWorkerBackendAvailability.NotQualified, "Synthetic worker Release requires an explicit internal fixture admission.");
        if (windows && request == GmWorkerBackendRequest.Auto)
            return new(request, capability, GmWorkerBackend.WindowsJob, GmWorkerBackendAvailability.Available,
                "windows-job", "Existing Windows Job path.", GmWorkerBackendAvailability.NotImplemented);
        if (!linux)
            return Unavailable(GmWorkerBackendAvailability.Unsupported, "Requested backend is unsupported on this platform.");
        if (request == GmWorkerBackendRequest.SystemdUser)
            return Unavailable(GmWorkerBackendAvailability.NotImplemented, "systemd-user adapter is not implemented or qualified in this build.");
        if (capability == GmWorkerRequiredCapability.WorkerRelease)
            return Unavailable(GmWorkerBackendAvailability.NotQualified, "Linux worker Release requires typed pool/quarantine and durable admission; no process was launched.");
        return new(request, capability, GmWorkerBackend.NativeLineage, GmWorkerBackendAvailability.PreflightRequired,
            NativeGuarantee, "systemd-user is not implemented; native-lineage package and runtime preflight are required before neutral-host launch.",
            GmWorkerBackendAvailability.NotImplemented);
    }
}

private sealed class SpiritualLifecycleTestLogger : ILogger<GameEngine>
{
    private readonly ConcurrentQueue<string> _messages = new();

    /// <inheritdoc/>
    public IDisposable? BeginScope<TState>(TState state) where TState : notnull => null;

    /// <inheritdoc/>
    public bool IsEnabled(LogLevel logLevel) => logLevel >= LogLevel.Information;

    /// <inheritdoc/>
    public void Log<TState>(LogLevel logLevel, EventId eventId, TState state, Exception? exception,
        Func<TState, Exception?, string> formatter)
    {
        if (!IsEnabled(logLevel))
            return;
        var message = formatter(state, exception) + (exception is null ? string.Empty : "\n" + exception);
        _messages.Enqueue(message.Length <= 2000 ? message : message[..2000]);
        while (_messages.Count > 24)
            _messages.TryDequeue(out _);
    }

    /// <summary>
    /// Formats retained phase and failure messages without reading or dumping session files.
    /// </summary>
    /// <returns>
    /// At most twenty-four messages, each bounded to two thousand characters.
    /// </returns>
    internal string Describe() => "Engine diagnostics:\n" + string.Join("\n", _messages);
}

